</section></div></main><script>document.addEventListener('DOMContentLoaded',()=>{const t=document.getElementById('listingType'),c=document.getElementById('businessCategory');const bindSchedule=()=>{document.querySelectorAll('.schedule-row').forEach(row=>{const closed=row.querySelector('.schedule-closed'),fields=row.querySelectorAll('input[type=time]');const sync=()=>fields.forEach(field=>field.disabled=closed.checked);closed.addEventListener('change',sync);sync()});const copy=document.getElementById('copyWeekdaySchedule');copy?.addEventListener('click',()=>{const source=document.querySelector('[data-day=mon]');['tue','wed','thu','fri'].forEach(day=>{const target=document.querySelector('[data-day='+day+']');target.querySelector('.schedule-closed').checked=source.querySelector('.schedule-closed').checked;const values=[...source.querySelectorAll('input[type=time]')].map(i=>i.value);target.querySelectorAll('input[type=time]').forEach((i,index)=>i.value=values[index]);target.querySelector('.schedule-closed').dispatchEvent(new Event('change'))})})};bindSchedule();if(!t||!c)return;const f=()=>{[...c.options].forEach(o=>{o.hidden=o.dataset.type!==t.value;o.disabled=o.hidden});if(c.selectedOptions[0]?.disabled)c.value=''};t.addEventListener('change',f);f()})</script></x-marketplace-layout>
